INSERT INTO mastery_prompts (module_id, role, title, prompt_text, sort_order, created_at, updated_at) VALUES
('D1.1', 'classroom', 'Differentiated Lesson Plan', 'I teach a [grade level] [subject area] class with a wide range of reading levels. Generate a differentiated lesson plan for a week-long unit on ''The Giver,'' with specific activities and assessments for struggling readers, on-level readers, and advanced readers. The plan should include a variety of instructional strategies, such as small-group instruction, literature circles, and project-based learning.', 0, NOW(), NOW()),
('D1.1', 'classroom', 'Personalized Learning Path', 'Create a personalized learning path for a [grade level] student who is struggling in algebra. The path should include a diagnostic assessment to identify the student''s specific areas of weakness, a series of online tutorials and practice exercises, and a project-based learning activity that allows the student to apply their knowledge to a real-world problem.', 1, NOW(), NOW()),
('D1.1', 'coach', 'Coaching Cycle Plan', 'I am an instructional coach working with a team of new teachers. Develop a coaching cycle plan for the first semester of the school year. The plan should include a variety of coaching activities, such as observations, co-teaching, and feedback conversations. The plan should also be aligned with the school''s instructional goals and the teachers'' individual needs.', 0, NOW(), NOW()),
('D1.1', 'coach', 'Professional Learning Community Facilitation Guide', 'Create a facilitation guide for a professional learning community (collaborative team) of math teachers. The guide should include a protocol for analyzing student work, a process for developing common assessments, and a structure for sharing best practices. The guide should also include strategies for building a collaborative and supportive collaborative team culture.', 1, NOW(), NOW()),
('D1.1', 'higher_ed', 'Course Redesign', 'I am a professor of educational leadership redesigning my course on school finance. How can I incorporate principles of social justice and equity into the course? Provide specific examples of readings, activities, and assessments that would help students to understand the relationship between school finance and educational equity.', 0, NOW(), NOW()),
('D1.1', 'higher_ed', 'Program Evaluation', 'Our university is conducting a program evaluation of our principal preparation program. Develop a mixed-methods research design to evaluate the effectiveness of the program. The design should include both quantitative and qualitative data collection methods, such as surveys, interviews, and focus groups. The design should also include a plan for analyzing the data and reporting the findings.', 1, NOW(), NOW()),
('D1.1', 'leader', 'School Improvement Plan', 'Our elementary school has been identified as a ''focus school'' by the state department of education due to low performance in math. Develop a comprehensive school improvement plan that addresses the root causes of our low performance and includes specific, measurable, achievable, relevant, and time-bound (SMART) goals. The plan should also include a budget and a timeline for implementation.', 0, NOW(), NOW()),
('D1.1', 'leader', 'Community Engagement Strategy', 'Our school district is facing declining enrollment and a budget shortfall. Develop a community engagement strategy to build support for our schools and advocate for increased funding. The strategy should include a variety of communication channels, such as social media, community forums, and partnerships with local businesses.', 1, NOW(), NOW()),
('D1.1', 'sped', 'Functional Behavior Assessment', 'A [grade level] student with an emotional disability is exhibiting aggressive behaviors in the classroom. Conduct a functional behavior assessment (FBA) to identify the function of the behavior and develop a positive behavior support plan (PBSP). The PBSP should include proactive strategies to prevent the behavior from occurring, as well as reactive strategies to respond to the behavior when it does occur.', 0, NOW(), NOW()),
('D1.1', 'sped', 'Transition Plan', 'Create a transition plan for a high school student with a mild intellectual disability who is interested in working with animals. The plan should include a variety of transition services, such as vocational training, job shadowing, and independent living skills instruction. The plan should also identify potential post-secondary education and employment opportunities.', 1, NOW(), NOW()),
('D1.1', 'support', 'Crisis Intervention Plan', 'Our school has experienced a recent tragedy. Develop a crisis intervention plan to support students, staff, and families. The plan should include procedures for communicating with the school community, providing counseling and support services, and returning to a normal school routine.', 0, NOW(), NOW()),
('D1.1', 'support', 'College and Career Readiness Program', 'Design a comprehensive college and career readiness program for our high school. The program should include a variety of activities and services, such as college and career fairs, financial aid workshops, and internship opportunities. The program should also track student progress and outcomes to ensure that all students are prepared for success after high school.', 1, NOW(), NOW()),
('D1.2', 'classroom', 'Differentiated Lesson Plan', 'I am a [grade level] teacher. My students have just taken a diagnostic assessment on multiplication. Based on the following data [data], create a differentiated lesson plan with activities for three tiers of learners: approaching, on-level, and advanced.', 0, NOW(), NOW()),
('D1.2', 'classroom', 'Student Goal-Setting Conference', 'I am preparing for a goal-setting conference with a student. Here is their dashboard data [data]. Generate a script for me to use during the conference, helping the student to reflect on their progress and set a new learning goal.', 1, NOW(), NOW()),
('D1.2', 'coach', 'Feedback on a Lesson Plan', 'I am an instructional coach. A teacher has shared their lesson plan and their class dashboard data with me. Provide feedback on the lesson plan, suggesting specific ways the teacher could use the dashboard data to make real-time adjustments during the lesson.', 0, NOW(), NOW()),
('D1.2', 'coach', 'collaborative team Data Dive', 'I am facilitating a collaborative team for the [grade level] [subject area] team. Here is their collective dashboard data [data]. Design a ''data dive'' protocol that will guide the team in analyzing the data, identifying a common challenge, and brainstorming instructional strategies to address it.', 1, NOW(), NOW()),
('D1.2', 'higher_ed', 'Grant Proposal', 'I am a university professor seeking funding for a research project on the effectiveness of real-time data dashboards in K-12 schools. Write a compelling introduction for a grant proposal, outlining the problem, the proposed solution, and the potential impact of the research.', 0, NOW(), NOW()),
('D1.2', 'higher_ed', 'Policy Brief', 'I am writing a policy brief for state legislators on the importance of investing in data infrastructure for schools. Using the latest research and data, write a 2-page brief that makes a strong case for funding and provides specific recommendations for policymakers.', 1, NOW(), NOW()),
('D1.2', 'leader', 'School Improvement Plan', 'I am a school principal. Our school improvement plan focuses on improving literacy outcomes. Based on our school-wide dashboard data [data], identify the top 3 priorities for the next quarter and suggest specific action steps for each.', 0, NOW(), NOW()),
('D1.2', 'leader', 'Data Story for the Community', 'I need to create a presentation for a community meeting about our school''s progress. Using the data from our dashboard [data], create a compelling data story that highlights our successes and challenges in a way that is accessible to a non-educator audience.', 1, NOW(), NOW()),
('D1.2', 'sped', 'IEP Progress Report Narrative', 'I am writing an IEP progress report for a student. Here is the data from their dashboard [data]. Write a narrative summary of the student''s progress toward their goals, including specific examples and data points.', 0, NOW(), NOW()),
('D1.2', 'sped', 'Assistive Technology Recommendation', 'A student with a learning disability is struggling to keep up with note-taking in class. Based on their dashboard data, which shows a discrepancy between their verbal participation and written output, recommend 3 assistive technology tools that could support them.', 1, NOW(), NOW()),
('D1.2', 'support', 'Targeted Intervention Group', 'I am a school counselor. Based on the following dashboard data [data], identify a group of students who would benefit from a small group intervention on anxiety management. Justify your selection and outline a 6-week plan for the group.', 0, NOW(), NOW()),
('D1.2', 'support', 'Restorative Circle Script', 'There has been a conflict between two students. I have their behavior data from the dashboard [data]. Generate a script for a restorative circle to help them resolve the conflict and repair the harm.', 1, NOW(), NOW()),
('D1.3', 'classroom', 'Differentiated Lesson Plan', 'I am a [grade level] teacher. My collaborative team is focused on improving student writing. Based on the attached student writing samples, generate a differentiated lesson plan that addresses the common errors in grammar and organization. Include a variety of activities for different learning styles and a rubric for assessment.', 0, NOW(), NOW()),
('D1.3', 'classroom', 'Student Data Analysis', 'I am a [grade level] [subject area] teacher. Here is the data from my recent genetics unit test. Analyze the data to identify the three most challenging concepts for my students. Then, generate a plan for re-teaching these concepts in a way that is engaging and interactive.', 1, NOW(), NOW()),
('D1.3', 'coach', 'Coaching Cycle Plan', 'I am an instructional coach. I am starting a coaching cycle with a teacher who wants to improve their use of formative assessment. Generate a coaching cycle plan that includes a pre-observation conference, a classroom observation, and a post-observation conference. For each step, suggest some key questions to ask and areas to focus on.', 0, NOW(), NOW()),
('D1.3', 'coach', 'collaborative team Facilitation Guide', 'I am an instructional coach who is facilitating a collaborative team for the first time. The collaborative team is focused on analyzing student work. Generate a facilitation guide that includes a step-by-step process for leading the collaborative team, some potential challenges to anticipate, and strategies for keeping the conversation focused and productive.', 1, NOW(), NOW()),
('D1.3', 'higher_ed', 'Case Study for Students', 'I am a professor of education. I want to create a case study for my program candidates about a challenging collaborative team meeting. Generate a case study that describes a disagreement between two teachers about how to interpret student data. The case study should end with a series of discussion questions that prompt my students to consider different perspectives and potential solutions.', 0, NOW(), NOW()),
('D1.3', 'higher_ed', 'Literature Review on AI in Education', 'I am a doctoral student in education. I am writing my dissertation on the use of AI in K-12 education. Generate a literature review that summarizes the current research on the benefits and challenges of using AI to support teaching and learning. The literature review should be organized by theme and include at least 10 citations from peer-reviewed journals.', 1, NOW(), NOW()),
('D1.3', 'leader', 'School Improvement Plan', 'I am a middle school principal. Our school improvement goal is to increase student engagement. Generate a list of five high-impact strategies that our collaborative teams can focus on to support this goal. For each strategy, provide a brief rationale and a link to a relevant resource.', 0, NOW(), NOW()),
('D1.3', 'leader', 'collaborative team Effectiveness Survey', 'I am a district administrator. I want to assess the effectiveness of our collaborative teams. Generate a survey for teachers that asks about the quality of their collaborative team meetings, the impact on their instruction, and their suggestions for improvement. The survey should be anonymous and take no more than 10 minutes to complete.', 1, NOW(), NOW()),
('D1.3', 'sped', 'IEP Goal Progress Monitoring', 'I am a special education teacher. Here are the IEP goals and progress monitoring data for one of my students. Analyze the data to determine if the student is on track to meet their goals. If not, suggest some adjustments to their instruction or services.', 0, NOW(), NOW()),
('D1.3', 'sped', 'Accommodations for State Testing', 'I am a special education case manager. I need to determine the appropriate accommodations for a student with a learning disability on the upcoming state ELA test. Based on the student''s IEP and a description of the test format, generate a list of recommended accommodations and a rationale for each.', 1, NOW(), NOW()),
('D1.3', 'support', 'Behavior Intervention Plan', 'I am a school counselor. I am working with a student who is exhibiting disruptive behavior in the classroom. Based on the attached functional behavior assessment (FBA), generate a behavior intervention plan (BIP) that includes proactive strategies, reactive strategies, and a system for tracking progress.', 0, NOW(), NOW()),
('D1.3', 'support', 'Small Group Counseling Plan', 'I am a school social worker. I am planning a small group counseling session for students who are struggling with anxiety. Generate a 6-week group counseling plan that includes a different topic for each week, a variety of activities, and a way to measure the impact of the group.', 1, NOW(), NOW()),
('D1.4', 'classroom', 'Personalized Learning Paths', 'Generate personalized learning paths for my [grade level] students in math, based on their pre-assessment data. The learning paths should include a variety of activities, resources, and assessments, and should be aligned with our district''s curriculum.', 0, NOW(), NOW()),
('D1.4', 'classroom', 'Automated Feedback', 'I have a set of 100 student essays. Provide feedback on each essay, focusing on grammar, mechanics, and organization. The feedback should be constructive and specific, and should help students to improve their writing.', 1, NOW(), NOW()),
('D1.4', 'coach', 'Video Analysis', 'I have a video of a teacher''s lesson. Analyze the video and provide feedback on the teacher''s instructional practices. The feedback should be specific, actionable, and aligned with our school''s instructional framework.', 0, NOW(), NOW()),
('D1.4', 'coach', 'Virtual Coaching', 'I am coaching a teacher who works in a remote school. Recommend a virtual coaching platform that will allow me to observe the teacher''s instruction and provide real-time feedback.', 1, NOW(), NOW()),
('D1.4', 'higher_ed', 'AI Ethics Curriculum', 'Develop a curriculum for a high school course on the ethical implications of artificial intelligence. The curriculum should include a variety of readings, activities, and assessments, and should be aligned with state and national standards.', 0, NOW(), NOW()),
('D1.4', 'higher_ed', 'Teacher Education Program', 'Design a academic program that prepares pre-service professionals to use AI to support student learning. The program should include coursework on AI, as well as opportunities for hands-on experience in K-12 classrooms.', 1, NOW(), NOW()),
('D1.4', 'leader', 'Predictive Analytics', 'Analyze our school''s data from the past five years and identify students who are at risk of not graduating. Recommend interventions and supports to help these students get back on track.', 0, NOW(), NOW()),
('D1.4', 'leader', 'Resource Optimization', 'Our school district is facing budget cuts. Analyze our current spending and recommend ways to optimize our resources to minimize the impact on student learning.', 1, NOW(), NOW()),
('D1.4', 'sped', 'Adaptive Assessments', 'Create an adaptive assessment for a student with a disability that adjusts the difficulty of the questions based on the student''s responses. The assessment should be aligned with the student''s IEP goals and should provide a more accurate measure of their abilities.', 0, NOW(), NOW()),
('D1.4', 'sped', 'Speech-to-Text', 'I have a student with a physical disability who is unable to write. Recommend a speech-to-text tool that will allow the student to complete written assignments independently.', 1, NOW(), NOW()),
('D1.4', 'support', 'Early Warning System', 'Develop an early warning system that identifies students who are struggling with social-emotional issues. The system should use a variety of data sources, such as attendance, grades, and discipline referrals, and should provide a tiered system of supports.', 0, NOW(), NOW()),
('D1.4', 'support', 'College and Career Planning', 'Create a personalized college and career plan for a high school student, based on their interests, skills, and academic record. The plan should include a list of potential colleges and careers, as well as information on financial aid and scholarships.', 1, NOW(), NOW()),
('D2.1', 'classroom', 'AI Debate Lesson', 'Act as a [grade level] social studies teacher. Create a week-long lesson plan where students research and debate the ethical implications of using AI in the criminal justice system. The lesson should include a variety of activities, including using AI to generate arguments for both sides of the debate, and a rubric for assessing the final debate.', 0, NOW(), NOW()),
('D2.1', 'classroom', 'AI for Differentiation', 'I am a [grade level] teacher with a student who is reading two grade levels below their peers. How can I use a specific, free AI tool to adapt a grade-level science article for this student? Provide a step-by-step process and an example of the adapted text.', 1, NOW(), NOW()),
('D2.1', 'coach', 'AI Coaching Cycle', 'Design a 6-week instructional coaching cycle focused on helping a team of [grade level] [subject area] teachers integrate AI-powered adaptive practice tools. The plan should include a clear goal, a schedule of meetings and classroom observations, and a method for measuring the impact on student learning.', 0, NOW(), NOW()),
('D2.1', 'coach', 'AI for Teacher Workflow', 'A teacher feels overwhelmed with their workload. As an instructional coach, recommend 3-5 ways they can use AI to automate or streamline their administrative tasks, such as lesson planning, grading, and parent communication. For each suggestion, recommend a specific tool and a prompt to get started.', 1, NOW(), NOW()),
('D2.1', 'higher_ed', 'AI in Teacher Ed', 'You are a professor in a academic program. Design a new course titled ''AI in the K-12 Classroom.'' The course should cover the history of AI in education, practical applications of AI tools, ethical considerations, and AI policy. Create a detailed course syllabus.', 0, NOW(), NOW()),
('D2.1', 'higher_ed', 'AI Research Agenda', 'As a university researcher, develop a 5-year research agenda to study the long-term impacts of K-12 AI policies on student outcomes and teacher practices. The agenda should include a series of potential studies, research questions, and methodologies.', 1, NOW(), NOW()),
('D2.1', 'leader', 'AI Policy Rollout', 'As a school principal, create a comprehensive plan for rolling out our new district AI policy to my staff. The plan should include a timeline, key communication points, and a schedule of professional development sessions for the first semester.', 0, NOW(), NOW()),
('D2.1', 'leader', 'AI Incident Response', 'A student has been caught using an AI tool to cheat on a major exam. As the assistant principal, write an email to the student''s parents explaining the situation, the school''s policy on AI and academic integrity, and the disciplinary consequences. The tone should be firm but fair.', 1, NOW(), NOW()),
('D2.1', 'sped', 'AI in an IEP Meeting', 'You are a special education teacher in an IEP meeting for a student with autism. The parents are concerned about their child using an AI-powered communication device. How would you explain the benefits of the device and address their concerns? Write a script for your explanation.', 0, NOW(), NOW()),
('D2.1', 'sped', 'AI for Transition', 'How can a special education case manager use AI to help a high school student with a disability explore post-secondary options? Provide a list of 3-5 specific AI tools and how they can be used to research colleges, careers, and independent living skills.', 1, NOW(), NOW()),
('D2.1', 'support', 'AI for Attendance', 'As a school social worker, I am concerned about chronic absenteeism. How can I use AI to analyze attendance data, identify at-risk students, and generate personalized outreach messages to their families? Describe a hypothetical workflow using a tool like a spreadsheet with AI capabilities.', 0, NOW(), NOW()),
('D2.1', 'support', 'AI for College Apps', 'A high school senior is struggling to write their college application essay. As a school counselor, how can you ethically guide the student in using an AI writing assistant? What are the do''s and don''ts you would share with the student?', 1, NOW(), NOW()),
('D2.2', 'classroom', 'Proactive Parent Communication', 'Act as a [grade level] English teacher. My students will be using an AI writing assistant for peer review on their next essay. Draft a comprehensive email to parents that anticipates their questions. Explain the tool, its learning benefits for improving revision skills, the guardrails I''ve put in place to prevent misuse, and how it aligns with our school''s academic integrity policy. The tone should be confident and reassuring.', 0, NOW(), NOW()),
('D2.2', 'classroom', 'Student-Led Conference Prep', 'I am preparing my [grade level] students for student-led conferences. I want them to explain to their parents how they use our AI-powered concept mapping tool to organize their ideas for research projects. Generate a short, student-friendly script and a visual guide (a simple flowchart or diagram) that a student could use to walk their parent through the process.', 1, NOW(), NOW()),
('D2.2', 'coach', 'Coaching Cycle Planning', 'Act as an instructional coach. I am starting a coaching cycle with a veteran teacher who is skeptical of AI. He feels it''s ''one more thing'' on his plate. Draft an email to him for our initial meeting. The goal is to build trust and find a low-lift, high-impact way for him to experiment with an AI tool that solves a problem he genuinely cares about, like reducing his grading time or creating more engaging lesson hooks. The tone should be empathetic and collaborative, not pushy.', 0, NOW(), NOW()),
('D2.2', 'coach', 'Leading a Book Study', 'I am facilitating a staff book study on a book about AI in education. For our next meeting, I want to model how to use AI to deepen our discussion. Generate a set of prompts that I can give to teachers to use with a large language model *during* the meeting. The prompts should ask the AI to act as a specific stakeholder (e.g., a student, a parent, a tech CEO) and critique a chapter of the book from that perspective.', 1, NOW(), NOW()),
('D2.2', 'higher_ed', 'Administrator Program Redesign', 'As a professor of educational leadership, I am redesigning our principal preparation program. The state has just mandated that all administrator candidates must demonstrate competency in leading AI integration. Create a detailed performance task for the program. The task should require candidates to develop a comprehensive, year-long AI communication and engagement plan for a fictional school district, complete with sample artifacts (e.g., newsletter text, town hall agenda, teacher PD plan).', 0, NOW(), NOW()),
('D2.2', 'higher_ed', 'Cross-Disciplinary Research Grant', 'I am a university professor seeking funding for a cross-disciplinary research project between the College of Education and the Computer Science department. The project will involve developing and piloting an AI-powered tool to help K-12 teachers identify and mitigate bias in instructional materials. Write the ''Statement of Need'' section for the grant proposal. It must clearly articulate the problem of biased educational materials and make a compelling case for why an AI-supported, interdisciplinary approach is uniquely positioned to solve it.', 1, NOW(), NOW()),
('D2.2', 'leader', 'AI Task Force Launch', 'As a district superintendent, I am launching a new AI in Education Task Force composed of teachers, parents, administrators, and students. Draft my opening remarks for the first meeting. The speech needs to set a collaborative tone, outline the task force''s mission to co-create our district''s AI strategic plan, and empower the members by emphasizing the importance of their diverse perspectives in shaping a responsible and equitable future for our schools.', 0, NOW(), NOW()),
('D2.2', 'leader', 'Handling a Media Inquiry', 'I am a middle school principal. A local news reporter just contacted me about a parent complaint they received regarding our school''s use of an AI-based math tutoring program. The parent is concerned about data privacy and screen time. Draft a calm, professional, and transparent response to the reporter. Acknowledge the parent''s concern, briefly explain the program''s educational benefits and our data security protocols, and invite the reporter for a follow-up conversation.', 1, NOW(), NOW()),
('D2.2', 'sped', 'Advocating in an IEP Meeting', 'Act as a special education advocate attending an IEP meeting for a non-verbal student. The school team is hesitant to try a new AI-powered communication device. Prepare a compelling, evidence-based argument for a trial period. Reference the specific features of the device, cite research on its effectiveness for similar students, and frame it as a critical step for ensuring the student''s right to a Free Appropriate Public Education (FAPE) by providing them a voice.', 0, NOW(), NOW()),
('D2.2', 'sped', 'Differentiated Family Workshop', 'I am a special education coordinator planning a workshop for families on using AI tools at home to support their children. I need two versions of the invitation and agenda. One version should be for families of students with mild to moderate disabilities, focusing on AI for homework support and organization. The second version should be for families of students with more significant disabilities, focusing on AI for communication and life skills.', 1, NOW(), NOW()),
('D2.2', 'support', 'Digital Citizenship Curriculum', 'As a school librarian, I am updating our K-5 digital citizenship curriculum. Create a new lesson plan for [grade level]rs titled ''Being a Good Human to AI.'' The lesson should include a discussion on why we shouldn''t be rude to AI chatbots, how AI learns from our interactions, and the importance of using respectful language online with both people and AI. Include an engaging activity and a short exit ticket.', 0, NOW(), NOW()),
('D2.2', 'support', 'Addressing AI-Fueled Rumors', 'I am a high school counselor. A rumor is spreading among students, fueled by an AI-generated image, that a particular student cheated on an exam. I need to address the student body in a morning announcement. Draft a script that addresses the harm of spreading misinformation, explains how AI can be used to create fake content, and reminds students of our school''s values of respect and integrity, without naming the student involved.', 1, NOW(), NOW()),
('D2.3', 'classroom', 'Differentiated Reading Passages', 'I am a [grade level] teacher. My class is studying the American Revolution. Generate three reading passages about the Boston Tea Party, one at a [grade level] [subject area] level, one at a [grade level] [subject area] level, and one at a [grade level] reading level. For each passage, include three comprehension questions.', 0, NOW(), NOW()),
('D2.3', 'classroom', 'Project-Based Learning Unit', 'I am a high school engineering teacher. I want to design a project-based learning unit where students use AI to design a solution to a local environmental problem. Outline a 6-week unit plan, including a project timeline, learning objectives, and assessment criteria.', 1, NOW(), NOW()),
('D2.3', 'coach', 'Video Coaching Analysis', 'I am an instructional coach. A teacher has shared a 15-minute video of their math lesson for feedback. Watch the video and provide three specific, time-stamped commendations and three questions for consideration to guide our coaching conversation.', 0, NOW(), NOW()),
('D2.3', 'coach', 'Personalized PD Playlist', 'I am a middle school instructional coach. A social studies teacher wants to learn more about using primary sources in the classroom. Curate a personalized professional development playlist for the teacher, including two articles, one video, and one podcast episode on the topic.', 1, NOW(), NOW()),
('D2.3', 'higher_ed', 'Grant Proposal for AI Research', 'I am a university professor seeking funding for a research project on the use of AI to support graduate student development. Generate a two-page letter of inquiry for a fictional foundation that supports educational innovation. The letter should outline the problem, proposed solution, and expected outcomes of the research.', 0, NOW(), NOW()),
('D2.3', 'higher_ed', 'Online Course Module', 'I am a professor of curriculum and instruction. I am developing an online course for in-service teachers on the topic of AI literacy. Design the first module of the course, including a brief introduction, two learning activities, and a formative assessment.', 1, NOW(), NOW()),
('D2.3', 'leader', 'Community Engagement Plan', 'I am a middle school principal. I want to develop a plan to engage our community in a conversation about responsible AI use in our school. Generate a one-page plan that includes a timeline of events, a list of stakeholders to involve, and a sample agenda for a community forum.', 0, NOW(), NOW()),
('D2.3', 'leader', 'Ethical AI Policy', 'I am a district superintendent. Draft a board policy on the ethical use of artificial intelligence in our schools. The policy should address data privacy, algorithmic bias, and the importance of human oversight.', 1, NOW(), NOW()),
('D2.3', 'sped', 'Assistive Technology Recommendation', 'I am a special education teacher working with a non-verbal [grade level] student with autism. Research and recommend three AI-powered augmentative and alternative communication (AAC) apps that could support the student''s communication in the classroom. For each app, provide a brief description and a link to its website.', 0, NOW(), NOW()),
('D2.3', 'sped', 'Transition Plan for a Student', 'I am a high school special education teacher. I am developing a transition plan for a [grade level] student with an intellectual disability who wants to work in the hospitality industry. Generate a list of five potential job skills to target and three local businesses that might offer internship opportunities.', 1, NOW(), NOW()),
('D2.3', 'support', 'Mental Health Resource Hub', 'I am a school psychologist. I want to create an online resource hub for students and families on the topic of mental health. Generate a list of 10 recommended resources, including websites, apps, and hotlines, that are appropriate for adolescents.', 0, NOW(), NOW()),
('D2.3', 'support', 'Restorative Justice Circle Prompts', 'I am a dean of students. I am facilitating a restorative justice circle for a group of [grade level] students who were involved in a conflict. Generate five restorative questions I can use to guide the conversation and help the students repair the harm.', 1, NOW(), NOW()),
('F1.1', 'classroom', 'Differentiated SEL Stations', 'Act as an expert [grade level] instructional coach specializing in SEL. I need to create a 45-minute, 3-station rotation activity focused on the CASEL competency of Self-Management. One station needs to be a technology-based activity using a free tool. One station should be a collaborative game, and the third should be an independent reflection. Provide detailed instructions and all necessary materials (worksheets, game rules, etc.) for each station, ensuring they are differentiated for students who need extra support and those who need a challenge.', 0, NOW(), NOW()),
('F1.1', 'classroom', 'Inclusive Classroom Library Audit', 'I am a [grade level] ELA teacher. I want to audit my classroom library to ensure it reflects the diversity of my students and promotes a sense of belonging. Act as an expert in culturally responsive pedagogy. Create a checklist I can use to evaluate my current library. Then, based on the goal of increasing representation of AAPI, LGBTQ+, and neurodivergent characters and authors, recommend 10 specific middle-grade book titles I should add. For each book, provide a brief, compelling summary and explain why it contributes to an inclusive library.', 1, NOW(), NOW()),
('F1.1', 'coach', 'AI-Driven Observation & Feedback', 'Demonstrate an expert instructional coaching workflow that uses AI to enhance the observation and feedback process. The goal is to help a [grade level] science teacher make their lab activities more collaborative and inclusive. Your response should include: 1) A pre-observation planning prompt to co-create a ''look-for'' checklist with the teacher. 2) A method for using AI to analyze a transcript of the class discussion to identify patterns of student participation. 3) A prompt to generate several data-driven, reflective questions for the post-observation coaching conversation.', 0, NOW(), NOW()),
('F1.1', 'coach', 'Building a ''Belonging'' Toolkit', 'Act as a lead instructional coach for a K-12 district. I want to create a ''Culture of Belonging Toolkit'' for all teachers on our district professional learning portal. The toolkit should be a one-stop-shop for practical, research-based strategies. Generate the structure and content for this toolkit, which must include: 1) A brief, compelling introduction to the ''why'' of belonging. 2) At least 15 distinct strategies, categorized by type (e.g., ''Classroom Environment'', ''Instructional Practices'', ''Building Relationships''). 3) For each strategy, provide a 1-2 sentence description and a link to an AI-generated resource (e.g., a lesson plan, a video script, a poster).', 1, NOW(), NOW()),
('F1.1', 'higher_ed', 'AI Ethics Case Study for Teachers', 'Act as a professor of education technology and ethics. Create a detailed case study for a graduate-level course for students in your program. The case study should present a realistic ethical dilemma involving a high school''s implementation of an AI-powered SEL curriculum. The dilemma should be complex, with no easy answer. Conclude the case study with a series of challenging discussion questions that force students to consider the perspectives of various stakeholders (students, teachers, parents, administrators) and apply ethical frameworks.', 0, NOW(), NOW()),
('F1.1', 'higher_ed', 'Grant Proposal for AI/SEL Research', 'I am a university researcher seeking funding to study the use of AI to support neurodivergent students'' social-emotional learning. Generate a compelling 2-page concept paper for a grant proposal to the National Science Foundation. The paper must include: 1) A statement of the problem and its significance. 2) A clear description of the proposed research, including the innovative use of a specific AI technology (e.g., personalized learning agents). 3) The research questions. 4) A brief overview of the methodology, including the partnership with a local school district. 5) The expected intellectual merit and broader impacts.', 1, NOW(), NOW()),
('F1.1', 'leader', 'Multi-Year SEL Vision', 'As a middle school principal, I need to develop a 3-year strategic vision for becoming a model school for AI-enhanced social-emotional learning. Our school has a diverse student body and a 1:1 device program. Your response should be a comprehensive plan that includes: a clear vision statement, year-by-year goals (Year 1: Foundational, Year 2: Integration, Year 3: Innovation), key performance indicators (KPIs) for each goal, a professional development plan for staff, and a budget proposal outlining key expenditures for tools, training, and personnel.', 0, NOW(), NOW()),
('F1.1', 'leader', 'Crisis Communication Plan', 'Act as an experienced district communications director. Our district has faced criticism from a parent group about our use of an AI tool that monitors student online activity for signs of self-harm. Draft a multi-pronged communication plan to address this. The plan must include: 1) A clear, empathetic, and transparent email to all parents explaining the purpose, function, and privacy safeguards of the tool. 2) Talking points for school board members and principals. 3) A public-facing FAQ document for the district website.', 1, NOW(), NOW()),
('F1.1', 'sped', 'AI-Powered IEP Meeting', 'I am a special education case manager preparing for an annual IEP meeting for a [grade level] student with ADHD and a specific learning disability in writing. The student struggles with executive functions and written expression. Demonstrate a mastery workflow using AI to prepare for and lead this meeting. Your response should include: 1) A prompt to generate a strengths-based present level of performance (PLOP) summary. 2) A prompt to create three ambitious but measurable IEP goals for writing and self-advocacy. 3) A prompt to design a sample accommodation and modification plan. 4) A script for how I would present the AI-generated goal ideas to the IEP team (including parents) for discussion and revision.', 0, NOW(), NOW()),
('F1.1', 'sped', 'De-escalation Scenarios', 'Act as a board-certified behavior analyst (BCBA). I work with students with significant emotional and behavioral challenges. I need to train paraprofessionals on de-escalation techniques. Create a set of five detailed, realistic scenarios of escalating student behavior in a special education classroom. For each scenario, provide a poor (but common) staff response and an exemplary, trauma-informed response. Explain the principles behind the exemplary response.', 1, NOW(), NOW()),
('F1.1', 'support', 'Tiered Support System Design', 'As a school counselor, I am tasked with redesigning our school''s Tier 2 and Tier 3 SEL/mental health support system. We have limited staff but want to provide more targeted support. Design a comprehensive system that leverages AI ethically and effectively. Include: 1) A process for identifying students using both data and teacher nomination. 2) A description of three different Tier 2 group interventions (e.g., ''check-in/check-out'', social skills groups) with AI-generated curriculum outlines. 3) A workflow for how AI can be used to monitor student progress and help determine when a student needs to move to Tier 3.', 0, NOW(), NOW()),
('F1.1', 'support', 'Restorative Justice Circle Script', 'Act as an expert in restorative practices. A conflict occurred between two [grade level] students involving a harmful social media post. I need to facilitate a restorative justice circle with the two students and a peer mediator. Generate a complete script for me to follow, including: the opening ceremony, establishing norms, the sequence of restorative questions for each participant, and a process for collaboratively deciding how to repair the harm.', 1, NOW(), NOW()),
('F1.2', 'classroom', 'Create a Behavior Plan', 'Act as an experienced elementary teacher. A student in my class, ''Leo'', is struggling with emotional regulation and often has outbursts when frustrated. Using the principles of PBIS and restorative justice, create a multi-faceted, Tier 2 behavior intervention plan for Leo. The plan should include: 1) two proactive strategies for me to use, 2) a simple self-regulation tool for Leo, and 3) a script for a restorative conversation with him after an outburst.', 0, NOW(), NOW()),
('F1.2', 'classroom', 'Differentiate Expectations', 'I am a [grade level] [subject area] teacher. My school is implementing PBIS. My behavioral expectation is ''Be Responsible.'' Generate three differentiated examples of what this looks like for a [grade level] general ed class, a [grade level] AP class, and an inclusion co-taught class. For each, provide one example related to homework and one related to class discussion.', 1, NOW(), NOW()),
('F1.2', 'coach', 'Create a Coaching Choice Board', 'Act as an instructional coach specializing in behavior. I am working with a team of [grade level] teachers. Create a coaching ''choice board'' focused on implementing Tier 1 restorative practices. The board should have 9 options, organized in a 3x3 grid, with activities ranging from reading an article, to observing a peer, to co-planning a class meeting. Each option should be a concrete, actionable task.', 0, NOW(), NOW()),
